extensibilityCode.vanilla:
import { createInlineCitation } from '@/components/ui/inline-citation';

// A EXCLUSÃO MÚTUA É DE QUEM MONTA A PÁGINA. A peça não conhece as vizinhas;
// quem as tem numa lista fecha as outras ao abrir uma.
const marcas = [];

for (const [i, citation] of citacoes.entries()) {
  const marca = createInlineCitation({
    citation,
    index: i + 1,
    labels: rotulosDe(i + 1, citation),
    onOpenChange: (aberta) => {
      if (!aberta) return;
      for (const outra of marcas) if (outra !== marca) outra.close();
    },
  });
  marcas.push(marca);
}

customizationCode.web:
/* A marca lê a superfície apagada do tema. Para destacá-la mais, troque o par
   de cores — nunca a altura, que é resultado do respiro e da entrelinha. */
.nds-inline-citation-marker {
  background-color: hsl(var(--accent) / 0.2);
}

/* A prévia herda a superfície flutuante compartilhada; o que é só dela é o
   espaço entre as linhas. */
.nds-inline-citation-panel {
  gap: var(--spacing-3);
}

